3	(function youtubeToolsResize() {
4	  const DEFAULTS = { behavior: "zoom", scale: 1.0, fullscreenOnly: true };
5	  const CLASS_NAME = "yt-tools-resized";
6	
7	  let state = { ...DEFAULTS };
8	
9	  function computeTransform(behavior, scale) {
10	    if (behavior === "off" || scale <= 1.0) return "";
11	    if (behavior === "stretch") return `scaleX(${scale})`;
12	    return `scale(${scale})`;
13	  }
14	
15	  function applyToVideos() {
16	    const isFullscreen = !!document.fullscreenElement;
17	    const shouldApply =
