  background: #111;
  color: #e0e0e0;
}

/* ── Tabs ── */
.tabs {
  display: flex;
  border-bottom: 1px solid #2a2a2a;
}

.tab {
  flex: 1;
  padding: 10px 0;
  background: none;
  border: none;
  color: #666;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  cursor: pointer;
  transition: color 0.15s, border-color 0.15s;
  border-bottom: 2px solid transparent;
}

.tab:hover:not(:disabled) {
  color: #aaa;
}

.tab.active {
  color: #fff;
  border-bottom-color: #fff;
}

.tab:disabled {
  color: #333;
  cursor: not-allowed;
}

/* ── Content ── */
.tab-content {
  display: none;
  padding: 16px;
}

.tab-content.active {
  display: block;
}

.control-group {
  margin-bottom: 14px;
}

.control-group:last-child {
  margin-bottom: 0;
}

.control-label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #888;
  margin-bottom: 8px;
}

/* ── Segmented Control ── */
.segmented {
  display: flex;
  gap: 6px;
}

.segmented input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.segmented label {
  flex: 1;
  text-align: center;
  padding: 7px 0;
  border: 1px solid #333;
  border-radius: 6px;
  color: #888;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s;
}

.segmented label:hover {
  border-color: #555;
  color: #ccc;
}

.segmented input:checked + label {
  border-color: #fff;
  color: #fff;
  background: #222;
}

/* ── Slider ── */
#scaleSlider {
