      const n = Number(value);
      slider.value = n.toFixed(2);
      scaleValue.textContent = n.toFixed(2) + "x";
      updateSliderTrack();
    }

    function saveScale(value) {
      renderScale(value);
      chrome.storage.local.set({ [STORAGE_KEYS.scale]: Number(value) });
    }

