"use strict";

(function youtubeToolsResize() {
  const DEFAULTS = { behavior: "zoom", scale: 1.0, fullscreenOnly: true, offsetX: 0, offsetY: 0 };
  const CLASS_NAME = "yt-tools-resized";

  let state = { ...DEFAULTS };

  function computeTransform(behavior, scale, ox, oy) {
    if (behavior === "off" || scale <= 1.0) return "";
    var s = behavior === "stretch" ? "scaleX(" + scale + ")" : "scale(" + scale + ")";
    if (ox !== 0 || oy !== 0) {
      s += " translate(" + ox + "%, " + oy + "%)";
    }
    return s;
  }

  function applyToVideos() {
    const isFullscreen = !!document.fullscreenElement;
    const shouldApply =
      state.behavior !== "off" &&
      state.scale > 1.0 &&
      (!state.fullscreenOnly || isFullscreen);

    const videos = document.getElementsByTagName("video");
    for (let i = 0; i < videos.length; i++) {
      const video = videos[i];
      if (shouldApply) {
        const transform = computeTransform(state.behavior, state.scale, state.offsetX, state.offsetY);
        video.style.setProperty("transform", transform, "important");
        video.style.setProperty("transform-origin", "center center", "important");
        video.classList.add(CLASS_NAME);
      } else if (video.classList.contains(CLASS_NAME)) {
        video.style.removeProperty("transform");
        video.style.removeProperty("transform-origin");
        video.classList.remove(CLASS_NAME);
      }
    }
  }

  function loadSettings() {
    chrome.storage.local.get(
      ["ytResize_behavior", "ytResize_scale", "ytResize_fullscreenOnly",
       "ytResize_offsetX", "ytResize_offsetY"],
      function (result) {
        state = {
          behavior: result.ytResize_behavior || DEFAULTS.behavior,
          scale: Number(result.ytResize_scale) || DEFAULTS.scale,
          fullscreenOnly:
            typeof result.ytResize_fullscreenOnly === "boolean"
              ? result.ytResize_fullscreenOnly
              : DEFAULTS.fullscreenOnly,
          offsetX: Number(result.ytResize_offsetX) || 0,
          offsetY: Number(result.ytResize_offsetY) || 0,
        };
        applyToVideos();
      }
    );
  }

  chrome.storage.onChanged.addListener(function (changes, area) {
    if (area !== "local") return;
    let changed = false;
    if (changes.ytResize_behavior) {
      state = { ...state, behavior: changes.ytResize_behavior.newValue };
      changed = true;
    }
    if (changes.ytResize_scale) {
      state = { ...state, scale: Number(changes.ytResize_scale.newValue) };
      changed = true;
    }
    if (changes.ytResize_fullscreenOnly) {
      state = { ...state, fullscreenOnly: changes.ytResize_fullscreenOnly.newValue };
      changed = true;
    }
    if (changes.ytResize_offsetX) {
      state = { ...state, offsetX: Number(changes.ytResize_offsetX.newValue) || 0 };
      changed = true;
    }
    if (changes.ytResize_offsetY) {
      state = { ...state, offsetY: Number(changes.ytResize_offsetY.newValue) || 0 };
      changed = true;
    }
    if (changed) applyToVideos();
  });

  document.addEventListener("fullscreenchange", function () {
    if (document.fullscreenElement) {
      createOverlay();
      attachOverlay();
      watchControls();
    } else {
      if (controlsObserver) {
        controlsObserver.disconnect();
        controlsObserver = null;
      }
      detachOverlay();
    }
    applyToVideos();
  });

  // YouTube is a SPA — watch for navigation
  let lastUrl = location.href;
  let navTimer = null;
  const observer = new MutationObserver(function () {
    if (location.href !== lastUrl) {
      lastUrl = location.href;
      clearTimeout(navTimer);
      navTimer = setTimeout(applyToVideos, 500);
    }
  });

  function init() {
    loadSettings();
    observer.observe(document.body, { childList: true, subtree: true });
  }

  // ── Fit helpers ──

  function applyFit(type) {
    var videos = document.getElementsByTagName("video");
    if (videos.length === 0) return;
    var video = videos[0];
    var scale;
    if (type === "fitWidth") {
      scale = window.innerWidth / video.clientWidth;
    } else {
      scale = window.innerHeight / video.clientHeight;
    }
    scale = Math.min(8.0, Math.max(1.0, +scale.toFixed(2)));
    chrome.storage.local.set({
      ytResize_behavior: "zoom",
      ytResize_scale: scale,
      ytResize_offsetX: 0,
      ytResize_offsetY: 0,
    });
  }

  // Popup message handler
  chrome.runtime.onMessage.addListener(function (message) {
    if (message.type === "fitWidth" || message.type === "fitHeight") {
      applyFit(message.type);
    }
  });

  // ── Fullscreen overlay ──

  var overlay = null;
  var controlsObserver = null;

  function injectOverlayStyle() {
    if (document.getElementById("yt-tools-fs-style")) return;
    var style = document.createElement("style");
    style.id = "yt-tools-fs-style";
    style.textContent = [
      ".yt-tools-fs { position:fixed !important; top:0 !important; right:0 !important; z-index:2147483647 !important; display:flex !important; align-items:flex-start; justify-content:flex-end; padding:10px 12px; pointer-events:none !important; }",
      ".yt-tools-fs-bar { display:flex; gap:6px; opacity:0; transition:opacity .25s; pointer-events:none; }",
      ".yt-tools-fs.yt-tools-show .yt-tools-fs-bar { opacity:1; pointer-events:auto; }",
      ".yt-tools-fs-btn { background:rgba(255,255,255,.08); border:1px solid rgba(255,255,255,.15); color:rgba(255,255,255,.6); padding:5px 12px; border-radius:4px; font:500 11px/1 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif; cursor:pointer; backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px); transition:background .15s,color .15s,border-color .15s; letter-spacing:.02em; }",
      ".yt-tools-fs-btn:hover { background:rgba(255,255,255,.18); border-color:rgba(255,255,255,.3); color:rgba(255,255,255,.9); }",
    ].join("\n");
    document.head.appendChild(style);
  }

  function createOverlay() {
    if (overlay) return;
    injectOverlayStyle();

    overlay = document.createElement("div");
    overlay.className = "yt-tools-fs";

    var bar = document.createElement("div");
    bar.className = "yt-tools-fs-bar";

    var btnWide = document.createElement("button");
    btnWide.className = "yt-tools-fs-btn";
    btnWide.textContent = "WideFit";
    btnWide.addEventListener("click", function (e) {
      e.stopPropagation();
      applyFit("fitWidth");
    });

    var btnTall = document.createElement("button");
    btnTall.className = "yt-tools-fs-btn";
    btnTall.textContent = "TallFit";
    btnTall.addEventListener("click", function (e) {
      e.stopPropagation();
      applyFit("fitHeight");
    });

    bar.appendChild(btnWide);
    bar.appendChild(btnTall);
    overlay.appendChild(bar);
  }

  function attachOverlay() {
    var fsEl = document.fullscreenElement;
    if (fsEl && overlay && overlay.parentNode !== fsEl) {
      fsEl.appendChild(overlay);
    }
  }

  function detachOverlay() {
    if (overlay && overlay.parentNode) {
      overlay.parentNode.removeChild(overlay);
    }
  }

  function watchControls() {
    if (controlsObserver) controlsObserver.disconnect();
    var player = document.getElementById("movie_player");
    if (!player || !overlay) return;

    function sync() {
      if (player.classList.contains("ytp-autohide")) {
        overlay.classList.remove("yt-tools-show");
      } else {
        overlay.classList.add("yt-tools-show");
      }
    }

    controlsObserver = new MutationObserver(function () { sync(); });
    controlsObserver.observe(player, { attributes: true, attributeFilter: ["class"] });
    sync();
  }

  if (document.readyState === "complete") {
    init();
  } else {
    window.addEventListener("load", init);
  }
