  cursor: pointer;
  transition: color 0.15s, border-color 0.15s;
  border-bottom: 2px solid transparent;
}

.tab:hover:not(:disabled) {
  color: #aaa;
}

.tab.active {
  color: #fff;
  border-bottom-color: #fff;
}

.tab:disabled {
  color: #333;
  cursor: not-allowed;
}

/* ── Content ── */
.tab-content {
  display: none;
  padding: 16px;
}

.tab-content.active {
  display: block;
}

.control-group {
  margin-bottom: 14px;
}

.control-group:last-child {
  margin-bottom: 0;
}

.control-label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #888;
  margin-bottom: 8px;
}

/* ── Segmented Control ── */
.segmented {
  display: flex;
  gap: 6px;
}

.segmented input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.segmented label {
  flex: 1;
  text-align: center;
  padding: 7px 0;
  border: 1px solid #333;
  border-radius: 6px;
  color: #888;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s;
}

.segmented label:hover {
  border-color: #555;
  color: #ccc;
}

.segmented input:checked + label {
  border-color: #fff;
  color: #fff;
  background: #222;
}

/* ── Slider ── */
#scaleSlider {
  width: 100%;
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  margin: 4px 0 8px 0;
}

#scaleSlider::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 2px;
  background: linear-gradient(
    90deg,
    #fff 0%,
    #fff var(--p, 0%),
    #333 var(--p, 0%)
  );
}

#scaleSlider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 14px;
  height: 14px;
  margin-top: -5px;
  border-radius: 50%;
  background: #fff;
  border: none;
  cursor: pointer;
}

/* ── Presets ── */
.presets {
  display: flex;
  gap: 4px;
}

.presets button {
  flex: 1;
  padding: 5px 0;
  font-size: 11px;
  border: 1px solid #333;
  border-radius: 4px;
  background: none;
  color: #888;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;
}

.presets button:hover {
  border-color: #555;
  color: #ccc;
}

/* ── Toggle ── */
.toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 12px;
  color: #888;
}

.toggle input {
  accent-color: #fff;
}

/* ── Fit presets ── */
.fit-presets {
  margin-top: 4px;
}

/* ── Offset pad ── */
.offset-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.offset-pad {
  flex: 1;
  aspect-ratio: 16 / 9;
  background:
    linear-gradient(to right, transparent calc(50% - .5px), #333 calc(50% - .5px), #333 calc(50% + .5px), transparent calc(50% + .5px)),
    linear-gradient(to bottom, transparent calc(50% - .5px), #333 calc(50% - .5px), #333 calc(50% + .5px), transparent calc(50% + .5px)),
    #1a1a1a;
  border: 1px solid #333;
  border-radius: 6px;
  position: relative;
  cursor: crosshair;
  touch-action: none;
}

.offset-dot {
  position: absolute;
  width: 10px;
  height: 10px;
  background: #fff;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  top: 50%;
  left: 50%;
  pointer-events: none;
  box-shadow: 0 0 4px rgba(0, 0, 0, .5);
}

.offset-reset {
  padding: 6px 10px;
  font-size: 11px;
  border: 1px solid #333;
  border-radius: 4px;
  background: none;
  color: #888;
  cursor: pointer;
  font-family: inherit;
  transition: all .15s;
  white-space: nowrap;
}

.offset-reset:hover {
  border-color: #555;
  color: #ccc;
}

/* ── About ── */
.about {
  text-align: center;
  padding: 24px 0;
}

.about a {
  color: #888;
  text-decoration: none;
  font-size: 13px;
  font-weight: 500;
  transition: color 0.15s;
}

.about a:hover {
  color: #fff;
}

/* ── Placeholder ── */
.placeholder {
  text-align: center;
  color: #444;
  padding: 24px 0;
  font-size: 12px;
}

