    // At 4x: factor=3 → ±150% (exactly reaches edge)
    // At 8x: factor=7 → ±350% (exactly reaches edge)
    if (ox !== 0 || oy !== 0) {
      var factor = Math.max(1, scale - 1);
      parts.push("translate(" + (-ox * factor) + "%, " + (-oy * factor) + "%)");
    }
    if (scale > 1.0) {
      parts.push(behavior === "stretch" ? "scaleX(" + scale + ")" : "scale(" + scale + ")");
    }
